    @Override
    public InterfaceDTO getDados() { // metodo getDados é chamado para salvar os dados
        CartaoDTO cartaoDTO = dto; // Usa a mesma instância do DTO atual que está sendo usado no painel
        cartaoDTO.numCartao = jtfNumeroCartao.getText(); // Pega o texto do jtfNome e Coloca no nome do dto atual.
        cartaoDTO.cvv = jtfCardVerificationValue.getText();
        cartaoDTO.tipo = (TipoCartao) jComboBox1.getSelectedItem();
        return cartaoDTO; //Retorna o dto atualizado para que o Controller use
    }

    @Override
    public void setDTO(InterfaceDTO dto) { //setDTO é chamado para preencher o painel com dados já existentes
        this.dto = (CartaoDTO) dto; // Cast - Converte o InterfaceDTO para CartaoDTO
        jtfNumeroCartao.setText(this.dto.numCartao); // Coloca o valor do nome no campo de texto.
        jtfCardVerificationValue.setText(this.dto.cvv);
        jComboBox1.setSelectedItem(this.dto.tipo);
    }


